{"thought": "I have the spec, shortest_path, and the existing test. Now implement the full function.", "action": {"tool": "write_file", "args": {"path": "src/routekit/plan_drop_route.py", "content": "from __future__ import annotations

from itertools import permutations
from typing import List, Mapping, Optional, Sequence, Tuple

from routekit.shortest_path import shortest_path


def plan_drop_route(adj: Mapping[str, Mapping[str, int]], origin: str, destination: str, drops: Sequence[str]) -> Optional[Tuple[int, List[str]]]:
    """
    Plan the shortest tour from ``origin`` to ``destination`` that visits all ``drops``.

    The drops may be visited in any order. For a given visiting order the route is the
    chain of ``shortest_path`` segments origin -> first drop -> ... -> last drop ->
    destination; segments are joined without repeating the depot where they meet.
    Returns ``(total_km, path)`` for the cheapest visiting order, or None if no order
    gives a complete route. With no drops this is simply the shortest route from
    ``origin`` to ``destination``.

    Ties on total km are broken by the order whose complete path has fewer legs, then
    by the visiting order that comes first alphabetically (comparing the sequences of
    drops).

    Raises ValueError if ``drops`` contains duplicates or more than 6 depots, and
    KeyError if ``origin``, ``destination`` or any drop is not in ``adj``.

    Example:
        net = {"S": {"A": 1, "B": 5}, "A": {"S": 1, "B": 1}, "B": {"S": 5, "A": 1, "T": 1}, "T": {"B": 1}}
        plan_drop_route(net, "S", "T", ["B", "A"]) == (3, ["S", "A", "B", "T"])
    """
    drops = list(drops)
    for code in (origin, destination, *drops):
        if code not in adj:
            raise KeyError(code)
    if len(drops) != len(set(drops)):
        raise ValueError("drops contains duplicates")
    if len(drops) > 6:
        raise ValueError("drops has more than 6 depots")

    def build(order: Sequence[str]) -> Optional[Tuple[int, List[str]]]:
        nodes = [origin, *order, destination]
        total = 0
        path: List[str] = []
        for a, b in zip(nodes, nodes[1:]):
            seg = shortest_path(adj, a, b)
            if seg is None:
                return None
            cost, spath = seg
            total += cost
            if not path:
                path = list(spath)
            else:
                path.extend(spath[1:])
        return total, path

    if not drops:
        return build([])

    best: Optional[Tuple[int, int, Tuple[str, ...], List[str]]] = None
    for order in permutations(drops):
        built = build(order)
        if built is None:
            continue
        total, path = built
        key = (total, len(path) - 1, order)
        if best is None or key < (best[0], best[1], best[2]):
            best = (total, len(path) - 1, order, path)
    if best is None:
        return None
    return best[0], best[3]
"}}, "messages": []}

